function sanitizeJsonString(text) {
  let result = '';
  let inString = false;
  let escaped = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      if (escaped) {
        result += ch;
        escaped = false;
        continue;
      }
      if (ch === '\\') {
        result += ch;
        escaped = true;
        continue;
      }
      if (ch === '"') {
        let j = i + 1;
        while (j < text.length && /\s/.test(text[j])) j++;
        const nextCh = text[j];
        if (nextCh === undefined || nextCh === ',' || nextCh === '}' || nextCh === ']' || nextCh === ':') {
          result += ch;
          inString = false;
        } else {
          result += '\\"';
        }
        continue;
      }
      if (ch === '\n') { result += '\\n'; continue; }
      if (ch === '\r') { result += '\\r'; continue; }
      if (ch === '\t') { result += '\\t'; continue; }
      result += ch;
    } else {
      if (ch === '"') {
        inString = true;
      }
      result += ch;
    }
  }
  return result;
}

function extractFirstJsonArray(text) {
  const start = text.indexOf('[');
  // 【修正部分】'[' が見つからない場合は明確なエラーを投げてリトライを誘発する
  if (start === -1) {
    throw new Error("AIの応答にJSON配列が含まれていません。出力形式の指示に従わなかった可能性があります。AIの生応答先頭: " + text.slice(0, 50));
  }
  let depth = 0;
  let inString = false;
  let escaped = false;
  for (let i = start; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      if (escaped) { escaped = false; continue; }
      if (ch === '\\') { escaped = true; continue; }
      if (ch === '"') { inString = false; continue; }
      continue;
    }
    if (ch === '"') { inString = true; continue; }
    if (ch === '[') depth++;
    if (ch === ']') {
      depth--;
      if (depth === 0) {
        return text.slice(start, i + 1);
      }
    }
  }
  return text.slice(start);
}

function repairDirtyJson(text) {
  let cleaned = text.replace(/\r?\n/g, " ");
  cleaned = cleaned.replace(/"(option_[a-d]|question|keyword|category_major|category_middle|question_type|test_name|answer|explanation)"\s*,/g, '"$1": "",');
  return cleaned;
}

function safeJsonParse(cleaned, errorPrefix) {
  try {
    return JSON.parse(cleaned);
  } catch (e1) {
    const sanitized = sanitizeJsonString(cleaned);
    try {
      return JSON.parse(sanitized);
    } catch (e2) {
      const repaired = repairDirtyJson(sanitized);
      try {
        return JSON.parse(repaired);
      } catch (e3) {
        throw new Error(errorPrefix + ': ' + e2.message);
      }
    }
  }
}

