function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const item = $input.first().json;
const partsArray = item?.content?.parts ?? item?.candidates?.[0]?.content?.parts ?? null;
const raw = Array.isArray(partsArray) && partsArray.length > 0
  ? partsArray.map(p => (p && typeof p.text === 'string') ? p.text : '').join('')
  : (item.text ?? item.content ?? '');

let cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
cleaned = extractFirstJsonArray(cleaned);

let patches = [];
try {
  patches = JSON.parse(cleaned);
} catch (e) {
  try {
    patches = JSON.parse(sanitizeJsonString(cleaned));
  } catch (e2) {
    patches = []; // 査読結果パース失敗時はフォールバックとしてパッチなしで続行
  }
}

if (!Array.isArray(patches)) patches = [];

const originalQuestions = $('Code in JavaScript').first().json.questions;
const targets = $('Select Targets').first().json.targets;
const examName = $('Select Targets').first().json.exam_name;

const patchMap = new Map();
patches.forEach(p => {
  if (p && typeof p.index === 'number' && p.changes && typeof p.changes === 'object') {
    patchMap.set(p.index, p.changes);
  }
});

const now = new Date().toISOString();

const finalItems = originalQuestions.map((q, i) => {
  const changes = patchMap.get(i) || {};
  const merged = { ...q, ...changes };

    merged.test_name = examName;
  if (targets[i]) {
    merged.category_major = targets[i].category_major;
    merged.category_middle = targets[i].category_middle;
    merged.question_type = targets[i].question_type;
  }

  let relatedTerms = merged.related_terms;
  if (Array.isArray(relatedTerms)) {
    relatedTerms = relatedTerms.filter(Boolean).join('、');
  } else if (relatedTerms == null) {
    relatedTerms = '';
  } else if (typeof relatedTerms !== 'string') {
    relatedTerms = String(relatedTerms);
  }

  let answer = (merged.answer || '').toString().trim().toUpperCase();
  const answerMatch = answer.match(/[A-D]/);
  answer = answerMatch ? answerMatch[0] : answer.charAt(0);

  return {
    json: {
      question_id: generateUUID(),
      created_at: now,
      ...merged,
      related_terms: relatedTerms,
      answer: answer,
    }
  };
});

return finalItems;

