const staticData = $getWorkflowStaticData('global');
const syllabus = staticData.syllabus || [];
const countMap = staticData.categoryCounts || {};
const keywordCountMap = staticData.keywordCountMap || {};
const questionTypeCountMap = staticData.questionTypeCounts || {};
const totalCount = staticData.totalCount || 0;

const MAX_AVOID_KEYWORDS = 20;

let scored = syllabus.map(s => {
  const actualCount = countMap[s.category_middle] || 0;
  const actualRatio = totalCount > 0 ? actualCount / totalCount : 0;
  const targetRatio = s.target_ratio;
  const fulfillmentRatio = targetRatio > 0 ? actualRatio / targetRatio : 999;
  return {
    category_major: s.category_major,
    category_middle: s.category_middle,
    target_ratio: targetRatio,
    actual_count: actualCount,
    fulfillment_ratio: fulfillmentRatio,
    _rand: Math.random(),
  };
});
scored.sort((a, b) => a.fulfillment_ratio !== b.fulfillment_ratio ? a.fulfillment_ratio - b.fulfillment_ratio : a._rand - b._rand);

const questionTypeMaster = staticData.questionTypeMaster || [];
const BATCH_SIZE = Math.max(
  0,
  Math.min(5, syllabus.length, questionTypeMaster.length || 5)
);

const syllabusTermsMap = {};
syllabus.forEach(s => {
  const raw = s.syllabus_terms;
  if (raw && String(raw).trim() !== '') {
    syllabusTermsMap[s.category_middle] = String(raw)
      .split(/[、,，]/)
      .map(t => t.trim())
      .filter(Boolean);
  } else {
    syllabusTermsMap[s.category_middle] = [];
  }
});

let targets = scored.slice(0, BATCH_SIZE).map(t => {
  const catCounts = keywordCountMap[t.category_middle] || {};
  const avoidKeywords = Object.keys(catCounts)
    .sort((a, b) => catCounts[b] - catCounts[a])
    .slice(0, MAX_AVOID_KEYWORDS);

  const allTerms = syllabusTermsMap[t.category_middle] || [];
  const usedSet = new Set(Object.keys(catCounts));
  const remainingTerms = allTerms.filter(term => !usedSet.has(term));

  let termMode;
  let termCandidates;
  if (allTerms.length === 0) {
    termMode = 'no_list';
    termCandidates = [];
  } else if (remainingTerms.length > 0) {
    termMode = 'has_list';
    termCandidates = remainingTerms;
  } else {
    termMode = 'list_exhausted';
    termCandidates = allTerms.slice().sort((a, b) => (catCounts[a] || 0) - (catCounts[b] || 0));
  }

  return {
    ...t,
    avoid_keywords: avoidKeywords,
    term_mode: termMode,
    term_candidates: termCandidates,
  };
});

let typeScored = questionTypeMaster.map(t => {
  const actualCount = questionTypeCountMap[t.question_type] || 0;
  const actualRatio = totalCount > 0 ? actualCount / totalCount : 0;
  const targetRatio = t.target_ratio;
  const fulfillmentRatio = targetRatio > 0 ? actualRatio / targetRatio : 999;
  return {
    question_type: t.question_type,
    definition: t.definition,
    target_ratio: targetRatio,
    actual_count: actualCount,
    fulfillment_ratio: fulfillmentRatio,
    _rand: Math.random(),
  };
});
typeScored.sort((a, b) => a.fulfillment_ratio !== b.fulfillment_ratio ? a.fulfillment_ratio - b.fulfillment_ratio : a._rand - b._rand);

let selectedTypes = typeScored.slice(0, BATCH_SIZE);
for (let i = selectedTypes.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [selectedTypes[i], selectedTypes[j]] = [selectedTypes[j], selectedTypes[i]];
}

targets = targets.map((t, i) => ({
  ...t,
  question_type: selectedTypes[i] ? selectedTypes[i].question_type : undefined,
  question_type_definition: selectedTypes[i] ? selectedTypes[i].definition : undefined,
}));

const questionTypeDefinitionsText = questionTypeMaster
  .map(t => `- ${t.question_type}: ${t.definition}`)
  .join('\n');
const questionTypeAllowedListText = questionTypeMaster
  .map(t => t.question_type)
  .join('、');

const categoryMajorList = staticData.categoryMajorList || [];
const categoryMajorListText = categoryMajorList.join('、');

const targetListText = targets
  .map((t, i) => {
    let keywordGuideText;
    if (t.term_mode === 'has_list') {
      keywordGuideText = ` ｜ 未出題の用語候補(リストの先頭を優先): ${t.term_candidates.join('、')}`;
    } else if (t.term_mode === 'list_exhausted') {
      keywordGuideText = ` ｜ この分野は用語リストを一巡済みです。以下の中からリスト先頭の用語を優先して選んで出題すること: ${t.term_candidates.join('、')}`;
    } else {
      keywordGuideText = t.avoid_keywords.length > 0
        ? ` ｜ 既出キーワード(使用禁止): ${t.avoid_keywords.join('、')}`
        : '';
    }
    return `${i + 1}問目: 大分類「${t.category_major}」 / 中分類「${t.category_middle}」 / 出題形式「${t.question_type}」${keywordGuideText}`;
  })
  .join('\n');

const addedCount = staticData.addedCount || 0;
const examName = staticData.qualificationName || '';

// 【追加】無限ループ対策:周回するたびにカウントアップし、上限を超えたら強制終了させる
staticData.loopCount = (staticData.loopCount || 0) + 1;
const loopCount = staticData.loopCount;
const maxLoops = 30; // 1周5問想定なので30周=最大150問生成の安全弁

return [{
  json: {
    targets,
    target_list_text: targetListText,
    question_type_definitions_text: questionTypeDefinitionsText,
    question_type_allowed_list_text: questionTypeAllowedListText,
    category_major_list_text: categoryMajorListText,
    exam_name: examName,
    added_count: addedCount,
    target_new: 100,
    loop_count: loopCount,
    max_loops: maxLoops,
    debug_info: { total_existing_questions: totalCount }
  }
}];

const syllabus = $('Get row(s) in sheet1').all().map(item => item.json);
const existingQuestions = $('Get row(s) in sheet').all().map(item => item.json);

const countMap = {};
const questionTypeCountMap = {};
existingQuestions.forEach(q => {
  const key = q.category_middle;
  countMap[key] = (countMap[key] || 0) + 1;
  if (q.question_type) {
    questionTypeCountMap[q.question_type] = (questionTypeCountMap[q.question_type] || 0) + 1;
  }
});

const categoryMajorList = [...new Set(syllabus.map(s => s.category_major).filter(Boolean))];
const qualificationNameRow = syllabus.find(s => s.qualification_name && String(s.qualification_name).trim() !== '');
const qualificationName = qualificationNameRow ? String(qualificationNameRow.qualification_name).trim() : '';

const staticData = $getWorkflowStaticData('global');
staticData.syllabus = syllabus;
staticData.categoryCounts = countMap;
staticData.questionTypeCounts = questionTypeCountMap;
staticData.totalCount = existingQuestions.length;
staticData.categoryMajorList = categoryMajorList;
staticData.qualificationName = qualificationName;

const keywordStatsRows = $('Get row(s) in sheet3').all().map(item => item.json);
const keywordCountMap = {};
keywordStatsRows.forEach(r => {
  const cat = r.category_middle;
  const kw = r.keyword;
  if (!cat || !kw) return;
  const cnt = parseInt(r.count, 10) || 0;
  if (!keywordCountMap[cat]) keywordCountMap[cat] = {};
  keywordCountMap[cat][kw] = cnt;
});
staticData.keywordCountMap = keywordCountMap;

staticData.questionTypeMaster = $('Get row(s) in sheet2').all().map(item => ({
  question_type: item.json.question_type,
  target_ratio: parseFloat(item.json.target_ratio),
  definition: item.json.definition,
}));

return $input.all();

const staticData = $getWorkflowStaticData('global');
if (!staticData.keywordCountMap) staticData.keywordCountMap = {};
const items = $input.all();

const touched = new Map();
items.forEach(item => {
  const cat = item.json.category_middle;
  const kw = item.json.keyword;
  if (!cat || !kw) return;
  if (!staticData.keywordCountMap[cat]) staticData.keywordCountMap[cat] = {};
  const newCount = (staticData.keywordCountMap[cat][kw] || 0) + 1;
  staticData.keywordCountMap[cat][kw] = newCount;
  touched.set(cat + '||' + kw, {
    key: cat + '||' + kw,   // ← 追加:照合用の複合キー
    category_middle: cat,
    keyword: kw,
    count: newCount
  });
});

return Array.from(touched.values()).map(v => ({ json: v }));

// 正規化用マスターリストを取得
const middleMaster = [...new Set($('Get row(s) in sheet1').all().map(i => i.json.category_middle))];
const majorMaster = [...new Set($('Get row(s) in sheet1').all().map(i => i.json.category_major))];
const typeMaster = [...new Set($('Get row(s) in sheet2').all().map(i => i.json.question_type))];

// 全角半角スペース・記号を除去して比較しやすくする
function normalize(str) {
  return String(str || '')
    .replace(/[　\s]/g, '')
    .replace(/[()（）・\-]/g, '');
}

// 完全一致 → 正規化後一致 → 部分一致(片方がもう片方を含む)の順で候補を探す
function resolveToMaster(value, masterList) {
  if (!value) return { resolved: null, matched: false };
  if (masterList.includes(value)) return { resolved: value, matched: true };

  const normValue = normalize(value);
  const exact = masterList.find(m => normalize(m) === normValue);
  if (exact) return { resolved: exact, matched: true };

  const partial = masterList.find(m => normalize(m).includes(normValue) || normValue.includes(normalize(m)));
  if (partial) return { resolved: partial, matched: true };

  return { resolved: value, matched: false }; // 一致なし:元の値を残しつつ要確認フラグを立てる
}

const items = $input.all();
return items.map(item => {
  const q = { ...item.json };

  const middleResult = resolveToMaster(q.category_middle, middleMaster);
  const majorResult = resolveToMaster(q.category_major, majorMaster);
  const typeResult = resolveToMaster(q.question_type, typeMaster);

  q.category_middle = middleResult.resolved;
  q.category_major = majorResult.resolved;
  q.question_type = typeResult.resolved;

  // どれか一致しなかった場合は要確認フラグを立てる(シート側に列を追加してもよい)
  q._needs_category_review = !(middleResult.matched && majorResult.matched && typeResult.matched);

  return { json: q };
});
